export const INTERCEPT_DECLARATIONS_FILE = "intercept.d.ts";

// A .d.ts without top-level import/export is a script, so these declarations
// are global and intercept/ files get types without importing anything.
export function interceptDeclarations(): string {
  return [
    "/**",
    " * Generated by backeneko. Rewritten on every start; do not edit.",
    " */",
    "",
    "interface ProxyPayload {",
    "  query: string;",
    "  variables?: Record<string, unknown> | null;",
    "  operationName?: string | null;",
    "}",
    "",
    'type InterceptRoute = "local" | "remote" | "split";',
    "",
    "interface InterceptContext {",
    "  operationName: string | null;",
    '  operationType: "query" | "mutation" | "subscription";',
    "  rootFields: string[];",
    "  route: InterceptRoute;",
    "  target: string | null;",
    "  query: string;",
    "  variables: Record<string, unknown> | null;",
    "  rootField?: string;",
    "  file: string;",
    "}",
    "",
    "interface InterceptResult {",
    "  data?: unknown;",
    "  errors?: readonly unknown[];",
    "  extensions?: Record<string, unknown>;",
    "}",
    "",
    'type InterceptMode = "auto" | "proxy" | "local";',
    "",
  ].join("\n");
}
